// Replace the jsCode in your "Word Count Analysis" node:
// UPDATED WORD COUNT ANALYSIS - EXPECTING TEXT INPUT

const inputData = $json.body || $json;
const extractedText = inputData.manuscriptText || '';
const fileName = inputData.fileName || 'manuscript.txt';
const manuscriptId = inputData.manuscriptId || 'unknown';
const phaseType = inputData.phaseType || 'developmental_editing';

// Validate required data
if (!manuscriptId) {
  throw new Error('Manuscript ID is required for word count analysis');
}

if (!extractedText || extractedText.length < 100) {
  throw new Error('No valid manuscript text provided');
}

// Phase mapping and detection
const phaseMap = {
  'developmental_editing': 1,
  'line_editing': 2, 
  'copy_editing': 3,
  'publishing_preparation': 4
};

const phaseNumber = phaseMap[phaseType] || 1;

// Phase titles and emojis for response
const phaseTitles = {
  1: 'Developmental Editing',
  2: 'Line Editing', 
  3: 'Copy Editing',
  4: 'Publishing Preparation'
};

const phaseEmojis = {
  1: '🟢',
  2: '🟣', 
  3: '🔴',
  4: '🟡'
};

console.log(`=== WORD COUNT ANALYSIS - ${phaseTitles[phaseNumber]} (Phase ${phaseNumber}) ===`);
console.log(`   Manuscript ID: ${manuscriptId}`);

// Word count analysis on clean text
const words = extractedText.match(/\S+/g) || [];
const wordCount = words.length;
const formattedWordCount = wordCount.toLocaleString();

// Text quality analysis
const sentences = extractedText.split(/[.!?]+/).filter(s => s.trim().length > 0);
const paragraphs = extractedText.split(/\n\s*\n/).filter(p => p.trim().length > 0);
const characters = extractedText.length;
const avgWordLength = words.length > 0 ? (characters / words.length).toFixed(2) : 0;
const estimatedReadingTime = Math.ceil(wordCount / 250);

// Classification and business logic
let classification = 'standard';
let canProceed = true;
let message = '';

if (wordCount < 1000) {
  classification = 'too_short';
  canProceed = false;
  message = 'Manuscript appears too short for professional analysis. Please ensure you\'ve uploaded your complete manuscript.';
} else if (wordCount > 150000) {
  classification = 'very_large';
  canProceed = false;
  message = 'Large manuscript detected. Please contact our team for premium processing.';
} else if (wordCount > 100000) {
  classification = 'large';
  message = 'Large manuscript - extended processing time expected.';
}

// Quality assessment
let extractionQuality = 'excellent';
if (wordCount < 100) extractionQuality = 'poor';
else if (wordCount < 1000) extractionQuality = 'fair';
else if (wordCount < 5000) extractionQuality = 'good';

// Processing time estimates
let processingTime = "1-3 minutes";
switch(phaseNumber) {
  case 1: // Developmental Editing
    if (wordCount > 75000) processingTime = "6-10 minutes";
    else if (wordCount > 50000) processingTime = "4-6 minutes";
    else if (wordCount > 25000) processingTime = "2-4 minutes";
    break;
  case 2: // Line Editing
    if (wordCount > 75000) processingTime = "4-7 minutes";
    else if (wordCount > 50000) processingTime = "3-5 minutes";
    else if (wordCount > 25000) processingTime = "2-3 minutes";
    break;
}

console.log(`✅ ${phaseTitles[phaseNumber]} analysis complete:`);
console.log(`   Word Count: ${formattedWordCount}`);
console.log(`   Classification: ${classification}`);
console.log(`   Can Proceed: ${canProceed}`);

// Quality metrics for history table
const qualityMetrics = {
  totalCharacters: characters,
  totalSentences: sentences.length,
  totalParagraphs: paragraphs.length,
  avgWordLength: parseFloat(avgWordLength),
  estimatedReadingTime: estimatedReadingTime,
  extractionQuality: extractionQuality
};

return {
  json: {
    success: true,
    manuscriptId: manuscriptId,
    wordCount: wordCount,
    formattedWordCount: formattedWordCount,
    classification: classification,
    canProceed: canProceed,
    message: message,
    extractionQuality: extractionQuality,
    processingTime: processingTime,
    fileName: fileName,
    phaseType: phaseType,
    phaseNumber: phaseNumber,
    phaseTitle: phaseTitles[phaseNumber],
    phaseEmoji: phaseEmojis[phaseNumber],
    qualityMetrics: qualityMetrics
  }
};

// FIXED FORMAT RESPONSE NODE - USING first() METHOD

// Get word count data from the Word Count Analysis node (using first() to access array)
const wordCountNode = $('Word Count Analysis').first().json;

// Get database update confirmation from PostgreSQL node
const dbUpdateData = $json;

// Create the unified formatted response for portal
const formattedResponse = {
  success: true,
  wordCount: wordCountNode.wordCount,
  formattedWordCount: wordCountNode.formattedWordCount,
  classification: wordCountNode.classification,
  canProceed: wordCountNode.canProceed,
  message: wordCountNode.message,
  extractionQuality: wordCountNode.extractionQuality,
  processingTime: wordCountNode.processingTime,
  quality: wordCountNode.qualityMetrics, // Note: qualityMetrics, not quality

  // Phase metadata (unified response)
  phaseType: wordCountNode.phaseType,
  phaseNumber: wordCountNode.phaseNumber,
  phaseTitle: wordCountNode.phaseTitle,
  phaseEmoji: wordCountNode.phaseEmoji,

  // Database update confirmation
  database: {
    updated: true,
    manuscriptId: wordCountNode.manuscriptId,
    updatedAt: new Date().toISOString(),
    currentWordCount: wordCountNode.wordCount
  },

  // File information
  fileInfo: {
    fileName: wordCountNode.fileName,
    analysisCompleted: true,
    lastChecked: new Date().toISOString(),
    phaseSpecific: true
  }
};

console.log(`✅ ${wordCountNode.phaseTitle} (Phase ${wordCountNode.phaseNumber}) formatted response:`);
console.log(`   Manuscript ID: ${wordCountNode.manuscriptId}`);
console.log(`   Word Count: ${wordCountNode.formattedWordCount}`);
console.log(`   Database Updated: ${formattedResponse.database.updated}`);

return {
  json: formattedResponse
};

